import type { GlossaryHubMeta, GlossaryTerm } from "./types"
import { GLOSSARY_SLUGS, type GlossarySlug } from "./slugs"

type TermCopy = { term: string; definition: string }
type LocaleCopy = { hub: GlossaryHubMeta; terms: TermCopy[] }

const RELATED_FORMATS: Partial<Record<GlossarySlug, string[]>> = {
  bitrate: ["mp3", "aac", "mp4"],
  codec: ["mp4", "mp3", "jpg"],
  "lossy-compression": ["mp3", "jpg", "aac"],
  "lossless-compression": ["flac", "png", "wav"],
  "container-format": ["mp4", "mkv", "avi"],
  "mime-type": ["pdf", "jpg", "json"],
  resolution: ["mp4", "jpg", "png"],
  dpi: ["jpg", "png", "pdf"],
  "alpha-channel": ["png", "webp"],
  metadata: ["jpg", "mp3", "mp4"],
  transcoding: ["mp4", "mp3", "webm"],
  "sample-rate": ["wav", "mp3", "flac"],
  "aspect-ratio": ["mp4", "jpg"],
  "color-space": ["jpg", "png", "pdf"],
  "vector-graphic": ["svg"],
  "raster-graphic": ["jpg", "png", "webp"],
  ocr: ["pdf", "docx"],
  "dpi-print": ["jpg", "png", "pdf"],
}

function buildTerms(copies: TermCopy[]): Record<GlossarySlug, GlossaryTerm> {
  return Object.fromEntries(
    GLOSSARY_SLUGS.map((slug, i) => [
      slug,
      {
        slug,
        term: copies[i].term,
        definition: copies[i].definition,
        ...(RELATED_FORMATS[slug] ? { relatedFormats: RELATED_FORMATS[slug] } : {}),
      },
    ]),
  ) as Record<GlossarySlug, GlossaryTerm>
}

